    public static class SojournerTruth
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://en.wikiquote.org/wiki/Sojourner_Truth", Text = "If women want any rights more than they're got, why don't they just take them, and not be talking about it?", Author = "Sojourner Truth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Sojourner_Truth", Text = "Well, children, when there is so much racket, there must be something out of kilter. I think that 'twixt the Negroes of the South and the women of the North, all talking about rights, the white men will be in a fix pretty soon.", Author = "Sojourner Truth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Sojourner_Truth", Text = "That man over there says that women need to be helped into carriages, and lifted over ditches, and to have the best place everywhere. Nobody ever helps me into carriages, or over mud-puddles, or gives me any best place! And ain't I a woman?", Author = "Sojourner Truth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Sojourner_Truth", Text = "I have ploughed and planted, and gathered into barns, and no man could head me! And ain't I a woman?", Author = "Sojourner Truth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Sojourner_Truth", Text = "I could work as much and eat as much as a man, when I could get it — and bear the lash as well! And ain't I a woman?", Author = "Sojourner Truth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Sojourner_Truth", Text = "I have borne thirteen children, and seen most all sold off to slavery, and when I cried out with my mother's grief, none but Jesus heard me! And ain't I a woman?", Author = "Sojourner Truth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Sojourner_Truth", Text = "That little man in black there, he says women can't have as much rights as men, 'cause Christ wasn't a woman! Where did your Christ come from? From God and a woman! Man had nothing to do with Him.", Author = "Sojourner Truth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Sojourner_Truth", Text = "If the first woman God ever made was strong enough to turn the world upside down all alone, the women together ought to be able to turn back and get it right side up again! And now they are asking to do it, the men had better let them.", Author = "Sojourner Truth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Sojourner_Truth", Text = "I have been forty years a slave and forty years free and would be here forty years more to have equal rights for all.", Author = "Sojourner Truth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Sojourner_Truth", Text = "Black women have been doing this for centuries, not only in Africa but certainly in the United States of America, whether it was picking cotton with the children bound on our backs, whether it is heading for freedom with the underground railroad, with the Sojourner Truths.", Author = "Sojourner Truth" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Sojourner_Truth", Text = "This is part of our history: we know we can bear arms and children.", Author = "Sojourner Truth" },
